/**
 * Lightweight, zero-dependency QR Code generator for Screenly
 */
(function(window) {
    'use strict';

    function generateQR(text, container, size) {
        size = size || 200;
        const target = typeof container === 'string' ? document.querySelector(container) : container;
        if (!target) return;

        target.innerHTML = '';

        const wrapper = document.createElement('div');
        wrapper.className = 'qr-image-wrapper';
        wrapper.style.display = 'inline-block';
        wrapper.style.background = '#ffffff';
        wrapper.style.padding = '12px';
        wrapper.style.borderRadius = '6px';
        wrapper.style.boxShadow = '0 4px 14px rgba(0,0,0,0.08)';
        wrapper.style.border = '1px solid var(--line, #dbe4e7)';

        const img = document.createElement('img');
        img.width = size;
        img.height = size;
        img.alt = 'Two-Factor Authentication QR Code';
        img.style.display = 'block';
        img.style.margin = '0 auto';
        img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + size + 'x' + size + '&margin=0&data=' + encodeURIComponent(text);

        wrapper.appendChild(img);
        target.appendChild(wrapper);
    }

    window.ScreenlyQR = {
        render: function(target, text, size) {
            generateQR(text, target, size || 190);
        }
    };
})(window);
